	arList=[["韩漫","manhwa"],["全年龄漫画","allages"],["BL/GL漫画","blgl"],["英文漫画","en-manga"]]
	arList.map(([tag,uri])=>{
		url=`{{getUrl()}}${uri}/page/{{page}}/`;
		push(tag, url, 1, 0.39);
		});
		orList=[["连载漫画","on-going"],["完结漫画","end"]]
		mrList=[["中文","zh"],["英文","en"]]
		orList.map(([teg,use])=>{
			push(teg,`{{getUrl()}}${use}/`,1,1);
			mrList.map(([tog,uro])=>{
			push(tog,`{{getUrl()}}${use}/${uro}/`,1,0.25)
			});
			});
