source.exploreUrl:
@js:
    java.toast("正在努力加载中，请稍后");

var sort = [];
var push = (title, url, type1, type2) => {
    sort.push ({
        title: title,
        url: url,
        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};

var x = [{
        u: "https://www.pdok.org/all/fl/1/",
        ti: "༺ˇ»`类型分类´«ˇ༻"
    },
    {
        u: "https://www.pdok.org/top/",
        ti: "༺ˇ»`排行分类´«ˇ༻"
    },
    {
        u: "https://www.pdok.org/quanben/all/1/",
        ti: "༺ˇ»`全本分类´«ˇ༻"
    }];

x.forEach (i => {
    var o = org.jsoup.Jsoup.parse(java.ajax(i.u));
    var s = o.select('ul.container a');
    push(i.ti, "", 1, 1);
    s.forEach((j,index) => {
        var url = String (j.attr("href")).replace(/(\d+)\/$/,"{{page}}/");
        if (index + 1 <= s.length - s.length % 3){
        push(j.text(), url, 1, 0.25)
        }else{
        	push(j.text(), url, -1, 0.29)
        	}
    })
});

JSON.stringify(sort);

ruleContent.content:
@js:
var a=src.match(/#booktxthtml'\)\.html\((x\("(.*)","(.*)","(.*)"\)\))/);
var da=java.base64DecodeToByteArray(JSON.parse('"'+a[2]+'"'));
var key=java.strToBytes(a[3]);
var iv=java.base64DecodeToByteArray(JSON.parse('"'+a[4]+'"'));
java.createSymmetricCrypto("AES/CBC/ZeroPadding", key, iv).decryptStr(da);

